          :class="b24ui.leadingAvatar({ class: props.b24ui?.leadingAvatar })"
        />
      </slot>

      <slot :b24ui="b24ui">
        <span v-if="props.label !== void 0 && props.label !== null" data-slot="label" :class="b24ui.label({ class: props.b24ui?.label })">
          {{ props.label }}
