      </slot>
    </Primitive>
    <slot name="trailing" :b24ui="b24ui">
      <Cross20Icon
        v-if="props.useClose"
        data-slot="trailingIcon"
        :class="b24ui.trailingIcon({ class: props.b24ui?.trailingIcon })"
